cat > /tmp/verify-i18n.test.ts << 'EOF'
import { describe, it, expect } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from './src/app.js'

describe('i18n sanity', () => {
  it('renders japanese login page for ja Accept-Language', async () => {
    const http = await TestApp.fromApp(app)
    const ja = http.withHeader('Accept-Language', 'ja-JP,ja;q=0.9,en-US;q=0.8,en;q=0.7')
    const res = await ja.get('/login')
    const text = await res.text()
    console.log('STATUS', res.status)
    console.log(text.includes('ログイン') ? 'HAS JA' : 'NO JA')
    console.log(text.slice(0, 2000))
  })

  it('renders english login page by default', async () => {
    const http = await TestApp.fromApp(app)
    const res = await http.get('/login')
    const text = await res.text()
    console.log(text.includes('Sign in') ? 'HAS EN' : 'NO EN')
  })
})
EOF
cp /tmp/verify-i18n.test.ts tests/zzverify.test.ts
bun test tests/zzverify.test.ts 2>&1 | tail -100
